// AppSigningCredential — Signing material's metadata; the secrets themselves never come back.
type AppSigningCredential struct {
	ID       string             `json:"id"`
	Platform AppSigningPlatform `json:"platform"`
	Label    string             `json:"label"`
	// SHA-256 of the stored material, to tell when it changed.
	BlobFingerprint      string  `json:"blobFingerprint"`
	CertificateExpiresAt *string `json:"certificateExpiresAt"`
	// The last successful build with it.
	LastVerifiedAt *string `json:"lastVerifiedAt"`
	// The bundle ID or Play package it signs for; empty for any app.
	AppIdentifier *string `json:"appIdentifier"`
	CreatedAt     string  `json:"createdAt"`
}

// AppSigningPlatform is one of the values below.
type AppSigningPlatform = string

const AppSigningPlatformApple AppSigningPlatform = "apple"
const AppSigningPlatformGoogle AppSigningPlatform = "google"
const AppSigningPlatformMacosDeveloperID AppSigningPlatform = "macos-developer-id"
const AppSigningPlatformWindowsAuthenticode AppSigningPlatform = "windows-authenticode"

