type SocialPerNetwork struct {
	// Used instead of the shared text on that network.
	TextOverride *string `json:"textOverride,omitempty"`
	// LinkedIn, Instagram: posted as a comment right after the post.
	FirstComment *string `json:"firstComment,omitempty"`
	// X: posted as a reply after the main post.
	ThreadFollowUp *string `json:"threadFollowUp,omitempty"`
	// Facebook: attached as the link.
	LinkPreviewURL *string `json:"linkPreviewUrl,omitempty"`
	// TikTok: the video's title.
	VideoTitle      *string  `json:"videoTitle,omitempty"`
	DisableDuet     *bool    `json:"disableDuet,omitempty"`
	DisableStitch   *bool    `json:"disableStitch,omitempty"`
	DisableComments *bool    `json:"disableComments,omitempty"`
	PollOptions     []string `json:"pollOptions,omitempty"`
	// At most 7 days.
	PollDurationMinutes *int `json:"pollDurationMinutes,omitempty"`
	// YouTube.
	Privacy *string `json:"privacy,omitempty"`
	// YouTube.
	CategoryID *string `json:"categoryId,omitempty"`
	// YouTube.
	MadeForKids *bool `json:"madeForKids,omitempty"`
	// YouTube.
	Tags []string `json:"tags,omitempty"`
	// Pinterest: the board, instead of the account's default.
	PinterestBoardID *string `json:"pinterestBoardId,omitempty"`
}

