// TaskCreateInput — POST /api/tasks — quick add: a CRM task in the workspace's Tasks space,
// assigned to the caller unless `assigneeUserId` says otherwise. With several
// Tasks spaces and no `spaceId`: 409 `tasksSpaceRequired` (`body.spaces`);
// with none: 409 `tasksSetupRequired` / `tasksNoSpace`.
type TaskCreateInput struct {
	WorkspaceID string `json:"workspaceId"`
	Title       string `json:"title"`
	// "YYYY-MM-DD" or an ISO instant.
	DueAt   *string `json:"dueAt,omitempty"`
	SpaceID *string `json:"spaceId,omitempty"`
	// One of: "normal", "low", "high", "urgent".
	Priority       *string         `json:"priority,omitempty"`
	AssigneeUserID *string         `json:"assigneeUserId,omitempty"`
	Recurrence     *TaskRecurrence `json:"recurrence,omitempty"`
	// Options of the space's labels column.
	Labels []string `json:"labels,omitempty"`
	// A CRM record to link the task to.
	Record *TaskCreateInputRecord `json:"record,omitempty"`
	// What it was made from — see `tasks.fromSource()`.
	Source          *TaskCreateInputSource `json:"source,omitempty"`
	EstimateMinutes *float64               `json:"estimateMinutes,omitempty"`
}

type TaskCreateInputRecord struct {
	DatabaseID string `json:"databaseId"`
	RecordID   string `json:"recordId"`
}

type TaskCreateInputSource struct {
	Kind       TaskOriginKind `json:"kind"`
	ID         string         `json:"id"`
	DocumentID *string        `json:"documentId,omitempty"`
	PageID     *string        `json:"pageId,omitempty"`
	SpaceID    *string        `json:"spaceId,omitempty"`
	RecordID   *string        `json:"recordId,omitempty"`
}

